package net.tecnihardcore;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class WeatherRulesTest {
    @Test void cosmeticDefaultAndExtendedRadius(){assertEquals(192,WeatherRules.DEFAULT_RADIUS);assertTrue(WeatherRules.settings(0,192,180,120,0));assertTrue(WeatherRules.settings(3,512,600,120,0));assertFalse(WeatherRules.settings(3,513,180,120,0));}
    @Test void widthCannotEscapeProtectedEnvelope(){assertEquals(324,WeatherRules.envelope(192,600));assertEquals(84,WeatherRules.envelope(32,120));assertTrue(WeatherRules.settings(0,192,180,600,0));assertFalse(WeatherRules.settings(0,192,180,601,0));}
    @Test void onlyExplicitTornadoQuakeAndMeteorsCanDestroy(){for(int t=0;t<5;t++){assertTrue(WeatherRules.settings(t,192,180,120,0));assertEquals(t<=1||t==4,WeatherRules.settings(t,192,180,120,4));}assertFalse(WeatherRules.settings(1,192,180,120,-1));assertFalse(WeatherRules.settings(0,192,180,120,21));}
    @Test void budgetsAreDifferentBoundedAndIncrease(){assertEquals(0,WeatherRules.blockBudget(0,0));assertEquals(0,WeatherRules.blockBudget(1,0));for(int i=1;i<=4;i++){assertTrue(WeatherRules.blockBudget(0,i)>WeatherRules.blockBudget(0,i-1));assertTrue(WeatherRules.blockBudget(1,i)>WeatherRules.blockBudget(1,i-1));assertNotEquals(WeatherRules.blockBudget(0,i),WeatherRules.blockBudget(1,i));}assertTrue(WeatherRules.blockBudget(0,4)<=160);assertTrue(WeatherRules.blockBudget(1,4)<=480);}
    @Test void QuakeCutsDeeperAndZeroNeverCuts(){assertEquals(0,WeatherRules.depth(0,0));assertEquals(0,WeatherRules.depth(1,0));assertTrue(WeatherRules.depth(1,4)>WeatherRules.depth(0,4));}
    @Test void roofAboveTipDoesNotLiftFloor(){assertEquals(65,WeatherRules.floor(-64,320,131,66,y->y<=64||y==130));}
    @Test void highAltitudeDoesNotRequireTwoHundredFreeWorldBlocks(){assertEquals(191,WeatherRules.floor(-64,320,191,300,y->y<=190));}
    @Test void surfaceFollowsDownhillAndClimbsSolidSlopes(){assertEquals(21,WeatherRules.floor(-64,320,21,65,y->y<=20));assertEquals(91,WeatherRules.floor(-64,320,91,65,y->y<=90));}
    @Test void caveFloorAndNegativeTerrainAreValid(){assertEquals(-39,WeatherRules.floor(-64,320,120,-20,y->y<=-40||y>=0&&y<120));assertEquals(-64,WeatherRules.floor(-64,320,-64,100,y->false));}
    @Test void cliffExtendsFunnelDownWhileCrownDescendsSmoothly(){double crown=WeatherRules.crown(296,40);assertEquals(295.5,crown);assertTrue(crown-40>200);assertEquals(350,WeatherRules.crown(296,150));}
    @Test void cratersAndVisibleFracturesScaleWithLevel(){for(int i=1;i<=4;i++){assertTrue(WeatherRules.craterRadius(i)>WeatherRules.craterRadius(i-1));assertTrue(WeatherRules.blockBudget(4,i)>WeatherRules.blockBudget(4,i-1));}assertEquals(16,WeatherRules.depth(1,4));assertEquals(5,WeatherRules.fractureWidth(4));assertEquals(7,WeatherRules.craterRadius(4));}
    @Test void motionIsFiftyPercentFasterAndWaitsThroughAlarm(){assertEquals(0,WeatherRules.angle(100));assertEquals(0,WeatherRules.angle(200));assertEquals(1,WeatherRules.angle(600));assertEquals(1.2,WeatherRules.orbit(192)/400*20,1e-9);}
    @Test void OnlyTornadoAcceptsTwentyLevels(){assertTrue(WeatherRules.settings(0,512,600,600,20));assertFalse(WeatherRules.settings(1,192,180,120,5));assertFalse(WeatherRules.settings(4,192,180,120,5));for(int i=1;i<=20;i++)assertTrue(WeatherRules.blockBudget(0,i)>WeatherRules.blockBudget(0,i-1));assertTrue(WeatherRules.depth(0,20)>=260);}
    @Test void WiderAndLargerTornadoAffectsMoreTerrainAndPullsFarther(){for(int width:new int[]{120,300,600}){assertTrue(WeatherRules.tornadoBudget(20,512,width)>=WeatherRules.tornadoBudget(20,192,width));assertTrue(WeatherRules.tornadoReach(512,width)>WeatherRules.tornadoReach(192,width));assertTrue(WeatherRules.tornadoDamageRadius(512,width)>WeatherRules.tornadoDamageRadius(192,width));}assertTrue(WeatherRules.tornadoForce(192,300)>WeatherRules.tornadoForce(192,120));assertTrue(WeatherRules.tornadoReach(512,600)>150);assertEquals(0,WeatherRules.tornadoBudget(0,512,600));assertTrue(WeatherRules.tornadoBudget(20,512,600)<=36000);}
    @Test void ViolentTornadoRipsHeavyConstructionOnlyAtExplicitHighLevels(){assertFalse(WeatherRules.uprootsHeavyBlocks(0,15));assertTrue(WeatherRules.uprootsHeavyBlocks(0,16));assertFalse(WeatherRules.uprootsHeavyBlocks(1,4));assertTrue(WeatherRules.tornadoBudget(20,512,600)>30000);assertEquals(0,WeatherRules.tornadoBudget(0,512,600));}
    @Test void RubbleDensityScalesButStaysBoundedForReducedGraphics(){assertTrue(WeatherRules.debrisCount(20,false,0)>1300);assertTrue(WeatherRules.debrisCount(20,true,0)<=512);assertTrue(WeatherRules.debrisCount(20,false,2)<=320);for(int i=1;i<=20;i++)assertTrue(WeatherRules.debrisCount(i,false,0)>=WeatherRules.debrisCount(i-1,false,0));}
}
